// Generator for the GaiZhongGai module device table.
// Usage: node scripts/openrgb/port-gaizonggai-devices.mjs <openrgb-root> <commit>
// Reads Controllers/GaiZongGaiKeyboardController/{GaiZhongGaiControllerDetect.cpp,
// RGBController_GaiZhongGai.cpp} and regenerates
// modules/gaizonggai/src/devices_table.rs. Do not edit by hand.
import fs from 'node:fs';
import path from 'node:path';
import { execFileSync } from 'node:child_process';

const root = process.argv[2] ?? process.env.OPENRGB_ROOT ?? '../openrgb';
const commit = process.argv[3] ?? 'unknown';
const family = path.join(root, 'Controllers', 'GaiZongGaiKeyboardController');
const detectPath = path.join(family, 'GaiZhongGaiControllerDetect.cpp');
const rgbPath = path.join(family, 'RGBController_GaiZhongGai.cpp');
const detect = fs.readFileSync(detectPath, 'utf8');
const rgb = fs.readFileSync(rgbPath, 'utf8');

const constants = Object.fromEntries(
  [...fs.readFileSync(path.join(family, 'GaiZhongGaiController.h'), 'utf8').matchAll(/#define\s+([A-Z][A-Z0-9_]*)\s+0x([0-9A-Fa-f]+)/g)].map((m) => [
    m[1],
    Number.parseInt(m[2], 16),
  ]),
);
if (constants.GAIZHONGGAI_VID == null) throw new Error('GAIZHONGGAI_VID not found');
const n = (s) => {
  const t = s.trim();
  if (t in constants) return constants[t];
  if (/^0x[0-9A-Fa-f]+$/.test(t)) return Number.parseInt(t, 16);
  if (/^\d+$/.test(t)) return Number.parseInt(t, 10);
  throw new Error(`unresolved constant ${t}`);
};

// Zone LED counts per PID from RGBController_GaiZhongGai.cpp SetupZones,
// limited to each case's own block up to the next case.
const source = rgb;
const occurrences = {};
for (const m of source.matchAll(/case (GAIZHONGGAI_[A-Z0-9_]+_PID):/g)) {
  (occurrences[m[1]] ??= []).push(m.index);
}
const ledsByPid = {};
for (const [pidDefine, list] of Object.entries(occurrences)) {
  const pid = n(pidDefine);
  let leds = 0;
  for (const pos of list) {
    const next = Math.min(
      ...Object.values(occurrences)
        .flat()
        .filter((p) => p > pos)
        .concat([source.length]),
    );
    const block = source.slice(pos, next);
    const m = block.match(/leds_max\s*=\s*(\d+)/);
    if (m) leds = Number.parseInt(m[1], 10);
  }
  ledsByPid[pid] = leds;
}

const rows = [];
for (const m of detect.matchAll(
  /REGISTER_HID_DETECTOR_I\s*\(\s*"([^"]+)"\s*,\s*([A-Za-z0-9_]+)\s*,\s*GAIZHONGGAI_VID\s*,\s*([A-Z][A-Z0-9_]+)\s*,\s*(\d+)\s*\)/g,
)) {
  const pid = n(m[3]);
  if (!Number.isFinite(pid)) throw new Error(`unresolved PID ${m[3]} in row ${m[1]}`);
  const leds = ledsByPid[pid] ?? 0; // 0 = device-derived count (hub/light board rows)
  rows.push({ name: m[1], handler: m[2], vid: constants.GAIZHONGGAI_VID, pid, interface: Number.parseInt(m[4], 10), leds });
}
if (rows.length !== 9) throw new Error(`expected 9 detector rows, got ${rows.length}`);

const out = path.join(process.cwd(), 'modules', 'gaizonggai', 'src', 'devices_table.rs');
fs.mkdirSync(path.dirname(out), { recursive: true });
const lines = [
  '// SPDX-License-Identifier: GPL-2.0-or-later',
  `// Generated by scripts/openrgb/port-gaizonggai-devices.mjs from OpenRGB ${commit}; do not edit.`,
  'use crate::table::Detector;',
  '',
  'pub const DETECTORS: &[Detector] = &[',
  ...rows.map((d) =>
    `    Detector { name: ${JSON.stringify(d.name)}, handler: ${JSON.stringify(d.handler)}, vid: 0x${d.vid.toString(16).padStart(4, '0')}, pid: 0x${d.pid.toString(16).padStart(4, '0')}, interface: ${d.interface}, leds: ${d.leds} },`,
  ),
  '];',
  '',
];
fs.writeFileSync(out, lines.join('\n'));
execFileSync(process.platform === 'win32' ? 'rustfmt.exe' : 'rustfmt', [out], { stdio: 'ignore' });
console.log(`generated ${rows.length} GaiZhongGai HID detectors`);